				return false;

			int maxValue = valueCount - 1;
			int selectValue;

			if (IsPushButton(UIManager.StickLRight, false))
			{
				if (item.itemType == SettingMenuItem.ItemType.Gauge)
					selectValue = Mathf.Min(item.selectIndex + 1, maxValue);
				else
					selectValue = UIManager.Repeat(item.selectIndex + 1, 0, maxValue);
			}
			else if (IsRepeatButton(UIManager.StickLRight, false))
			{
				selectValue = Mathf.Min(item.selectIndex + 1, maxValue);
			}
			else if (IsPushButton(UIManager.StickLLeft, false))
			{
				if (item.itemType == SettingMenuItem.ItemType.Gauge)
					selectValue = Mathf.Max(item.selectIndex - 1, 0);
				else
					selectValue = UIManager.Repeat(item.selectIndex - 1, 0, maxValue);
			}
			else if (IsRepeatButton(UIManager.StickLLeft, false))
			{
				selectValue = Mathf.Max(item.selectIndex - 1, 0);
			}
