		private bool SetSelectValue(int selectValue) {
			SettingMenuItem item = _activeItems[_selectIndex];
			if (!item.SetSelectIndex(selectValue, true, true))
				return false;

			if (item.configId == ConfigID.MessageSpeed || item.configId == ConfigID.LangJpnMode)
				OpenDescriptionMessageWindow();

			if (item.configId == ConfigID.VoiceVolume)
			{
				_voiceInstance?.Stop();
				_voiceInstance = AudioManager.Instance.PlayVoice(AK.EVENTS.PLAY_PV_399_00_00, AK.EVENTS.STOP_VOICE, (AudioInstance instance) =>
				{
					if (_voiceInstance == instance)
						_voiceInstance = null;
				});
			}
			else
			{
				AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_SELECT, null);
			}

			return true;
		}
